        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.isAnimating = false;

                this.setupNavDots();
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupWheelNav();
                this.updateUI();

                // Force initial state update
                setTimeout(() => this.goToSlide(0), 100);
            }

            setupIntersectionObserver() {
                const options = {
                    root: null,
                    rootMargin: '0px',
                    threshold: 0.5
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            // Update current index based on scroll position
                            const index = Array.from(this.slides).indexOf(entry.target);
                            if (index !== -1 && index !== this.currentSlide) {
                                this.currentSlide = index;
                                this.updateUI();
                            }
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupNavDots() {
                const container = document.getElementById('navDots');
                if (!container) return;

                this.slides.forEach((_, index) => {
                    const dot = document.createElement('button');
                    dot.className = 'nav-dot';
                    dot.setAttribute('aria-label', `Go to slide ${index + 1}`);
                    dot.addEventListener('click', () => this.goToSlide(index));
                    container.appendChild(dot);
                });
            }

            setupKeyboardNav() {
                window.addEventListener('keydown', (e) => {
                    if (this.isAnimating) return;

                    if (['ArrowDown', 'ArrowRight', 'Space', 'PageDown'].includes(e.code) || e.key === ' ') {
                        e.preventDefault();
                        this.nextSlide();
                    } else if (['ArrowUp', 'ArrowLeft', 'PageUp'].includes(e.code)) {
                        e.preventDefault();
                        this.prevSlide();
                    }
                });
            }

            setupTouchNav() {
                let touchStartY = 0;
                let touchEndY = 0;

                window.addEventListener('touchstart', e => {
                    touchStartY = e.changedTouches[0].screenY;
                }, {passive: true});

                window.addEventListener('touchend', e => {
                    touchEndY = e.changedTouches[0].screenY;
                    this.handleSwipe(touchStartY, touchEndY);
                }, {passive: true});
            }

            setupWheelNav() {
                let wheelTimeout;
                window.addEventListener('wheel', (e) => {
                    // Prevent default scrolling to handle it manually
                    e.preventDefault();

                    if (this.isAnimating) return;

                    clearTimeout(wheelTimeout);
                    wheelTimeout = setTimeout(() => {
                        if (e.deltaY > 50) this.nextSlide();
                        else if (e.deltaY < -50) this.prevSlide();
                    }, 50); // Debounce wheel events
                }, { passive: false });
            }

            handleSwipe(startY, endY) {
                if (this.isAnimating) return;
                const threshold = 50;
                if (startY - endY > threshold) this.nextSlide();
                else if (endY - startY > threshold) this.prevSlide();
            }

            nextSlide() {
                if (this.currentSlide < this.slides.length - 1) {
                    this.goToSlide(this.currentSlide + 1);
                }
            }

            prevSlide() {
                if (this.currentSlide > 0) {
                    this.goToSlide(this.currentSlide - 1);
                }
            }

            goToSlide(index) {
                this.isAnimating = true;
                this.currentSlide = index;

                this.slides[index].scrollIntoView({ behavior: 'smooth' });
                this.updateUI();

                setTimeout(() => { this.isAnimating = false; }, 800);
            }

            updateUI() {
                // Update progress bar
                const progressBar = document.getElementById('progressBar');
                if (progressBar) {
                    const progress = ((this.currentSlide) / (this.slides.length - 1)) * 100;
                    progressBar.style.width = `${progress}%`;
                }

                // Update dots
                const dots = document.querySelectorAll('.nav-dot');
                dots.forEach((dot, index) => {
                    if (index === this.currentSlide) dot.classList.add('active');
                    else dot.classList.remove('active');
                });
            }
        }

        // Initialize presentation
        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
